// Chunk B: adds the entire `terms` block to all 7 secondary languages
// (da, fi, cs, ro, hu, el, tr). 31 keys × 7 langs = 217 strings.
//
// Run from repo root:  node scripts/fill-gap-B-terms.js

const fs = require('fs');
const path = require('path');

const FILE = path.join(__dirname, '..', 'client', 'src', 'i18n-translations.js');
let content = fs.readFileSync(FILE, 'utf8');

// =====================================================================
// Helper to build a 31-key Terms object from 14 section title/body pairs
// =====================================================================
function makeTerms(meta, secs) {
  const obj = {
    title: meta.title,
    seoDesc: meta.seoDesc,
    updated: meta.updated,
  };
  for (let i = 0; i < 14; i++) {
    obj[`s${i + 1}Title`] = secs[i][0];
    obj[`s${i + 1}Body`] = secs[i][1];
  }
  return obj;
}

